import { useEffect, useState } from "react";
import { getVersion } from "@tauri-apps/api/app";
import { Box } from "@/shared/ui/layout/Box";
import { Text } from "@/shared/ui/typography/Text";

interface StatusBarProps {
  extra?: React.ReactNode;
}
// Preview-only stand-ins for the real `useAppStore` per-field reads (claudeApiKey/githubConnected/tabs) —
// the store is app-internal (unresolvable in this sandbox). Same shape, just a fixed sample instead of live.
const SAMPLE_CLAUDE_OK = true;
const SAMPLE_GITHUB_CONNECTED = true;
const SAMPLE_TABS = [{ layout: "1×1" }, { layout: "2×1" }];

export function StatusBar({ extra }: StatusBarProps) {
  // The real app version (from tauri.conf.json); drops the old hardcoded
  // "vX · rust Y" string (#215). Empty in a non-Tauri/web context — guarded because outside a real
  // Tauri runtime (e.g. this preview sandbox) `getVersion()` returns null rather than a Promise.
  const [appVersion, setAppVersion] = useState("");
  useEffect(() => {
    const result = getVersion?.();
    if (result && typeof result.then === "function") {
      result.then(setAppVersion).catch(() => setAppVersion(""));
    }
  }, []);

  const claudeOk = SAMPLE_CLAUDE_OK;
  const githubConnected = SAMPLE_GITHUB_CONNECTED;
  const tabs = SAMPLE_TABS;
  const totalPanes = tabs.reduce((sum, tab) => {
    const [c, r] = tab.layout.split("×").map(Number);
    return sum + c * r;
  }, 0);

  return (
    <Box className="statusbar">
      <Box className="s">
        <i className={claudeOk ? "" : "off"} />
        claude · {claudeOk ? "connected" : "no key"}
      </Box>
      <Box className="s">
        <i className={githubConnected ? "" : "off"} />
        github · {githubConnected ? "synced" : "not connected"}
      </Box>
      <Box className="spacer" />
      {extra}
      <Box className="s" style={{ color: "var(--fg-dim)" }}>
        {tabs.length} {tabs.length === 1 ? "tab" : "tabs"} · {totalPanes} {totalPanes === 1 ? "pane" : "panes"}
      </Box>
      {appVersion && <Text as="div">v{appVersion}</Text>}
    </Box>
  );
}
